/* Progressive enhancement: original fields and submission handlers are retained. */
(()=>{'use strict';function enhance(){document.querySelectorAll('dialog[open] fieldset').forEach(field=>{if(field.dataset.teamPicker||!field.querySelector('input[name="collaborators"]'))return;field.dataset.teamPicker='true';const form=field.closest('form'),owner=form?.querySelector('select[name="owner"]'),detail=field.querySelector('.dialog-collaborators')||field,labels=[...field.querySelectorAll('label')].filter(l=>l.querySelector('input[name="collaborators"]'));if(!labels.length)return;const target=field.querySelector('.dialog-collaborators>div')||field,box=document.createElement('div');box.className='team-picker';const search=document.createElement('input');search.type='search';search.placeholder='جست‌وجوی نام همکار';search.setAttribute('aria-label','جست‌وجوی نام همکار');const selected=document.createElement('div');selected.className='team-selected';const groups=document.createElement('div');groups.className='team-groups';const intern=document.createElement('section'),extern=document.createElement('section');intern.innerHTML='<h4>اعضای پروژه</h4>';extern.innerHTML='<h4>افراد بدون پنل</h4>';groups.append(intern,extern);labels.forEach(l=>{l.classList.add('team-choice');const input=l.querySelector('input'),id=input.value;let external=false;if(document.body.classList.contains('shared-app'))external=!!members.find(m=>m.id===id)?.external;else external=!!members[Number(id)]?.external;(external?extern:intern).append(l)});box.append(selected,search,groups);target.append(box);function update(){const query=search.value.trim(),names=[];labels.forEach(l=>{const i=l.querySelector('input'),isOwner=owner?.value===i.value;if(isOwner)i.checked=false;i.disabled=isOwner;l.hidden=isOwner||!l.textContent.includes(query);l.classList.toggle('chosen',i.checked);if(i.checked)names.push(l.textContent.trim())});selected.textContent=names.length?'همکاران انتخاب‌شده: '+names.join('، '):'همکاری انتخاب نشده است';for(const section of [intern,extern])section.hidden=![...section.querySelectorAll('label')].some(l=>!l.hidden);const summary=detail.querySelector(':scope > summary');if(summary)summary.textContent='همکاران'+(names.length?' · '+names.length+' نفر':' (اختیاری)')};search.oninput=update;box.addEventListener('change',update);owner?.addEventListener('change',update);update()})}new MutationObserver(enhance).observe(document.body,{childList:true,subtree:true});enhance()})();
